// Generates SqliteGrammar.g.cs, SQLite's LALR(1) parser tables and keyword list, from a SQLite source tree.
//
// SQLite's parser is generated by Lemon from parse.y; parse.c holds the tables. Porting the tables, not the grammar,
// makes this library accept exactly the SQL that SQLite accepts. Run it again when moving to a newer SQLite:
//
//     dotnet run --project tools/SqliteGrammarGenerator -- <dir with parse.c and mkkeywordhash.c> <version> [output]
//
// parse.c comes from a SQLite amalgamation or a built source tree (it is generated, so it is not in the repository at
// github.com/sqlite/sqlite). mkkeywordhash.c is tool/mkkeywordhash.c in that repository. Write the output over
// src/MBW.Utilities.ManagedSqlite.Sql/Internal/Grammar/SqliteGrammar.g.cs; it defaults to SqliteGrammar.g.cs in the
// current directory.

using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

// The numbers in the output are C# literals, whatever the machine's culture
CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;

if (args.Length < 2)
{
    Console.Error.WriteLine("usage: SqliteGrammarGenerator <dir with parse.c and mkkeywordhash.c> <version> [output]");
    return 1;
}

string src = args[0];
string version = args[1];
string output = args.Length > 2 ? args[2] : "SqliteGrammar.g.cs";
string parseC = File.ReadAllText(Path.Combine(src, "parse.c"));
string keywordsC = File.ReadAllText(Path.Combine(src, "mkkeywordhash.c"));

// The token codes, each name once, in the order parse.c defines them
List<(string Name, int Value)> tokens = new();
HashSet<string> seen = new();
foreach (Match m in Regex.Matches(parseC, @"#define TK_(\w+)\s+(\d+)"))
    if (seen.Add(m.Groups[1].Value))
        tokens.Add((m.Groups[1].Value, int.Parse(m.Groups[2].Value)));

// Keywords whose feature mask is enabled in a default build (no SQLITE_OMIT_*, no SQLITE_ENABLE_ORDERED_SET_AGGREGATES)
HashSet<string> disabled = new() { "ORDERSET" };
string table = Required(Regex.Match(keywordsC, @"static Keyword aKeywordTable\[\] = \{(.*?)\n\};", RegexOptions.Singleline), "aKeywordTable in mkkeywordhash.c");
List<(string Keyword, string Token)> keywords = new();
foreach (Match m in Regex.Matches(table, @"\{\s*""(\w+)"",\s*""TK_(\w+)"",\s*([\w|]+),"))
    if (!m.Groups[3].Value.Split('|').Any(disabled.Contains))
        keywords.Add((m.Groups[1].Value, m.Groups[2].Value));

string[] consts =
{
    "YYNSTATE", "YYNRULE", "YYNTOKEN", "YY_MAX_SHIFT", "YY_MIN_SHIFTREDUCE", "YY_MAX_SHIFTREDUCE",
    "YY_ERROR_ACTION", "YY_ACCEPT_ACTION", "YY_NO_ACTION", "YY_MIN_REDUCE", "YY_MAX_REDUCE", "YYWILDCARD",
    "YYNOCODE", "YY_SHIFT_COUNT", "YY_REDUCE_COUNT", "YY_ACTTAB_COUNT"
};

List<string> lines = new()
{
    "// <auto-generated>",
    $"// Generated by tools/SqliteGrammarGenerator from SQLite {version}'s parse.c and tool/mkkeywordhash.c.",
    "// Do not edit; run the generator again instead. SQLite is in the public domain.",
    "// </auto-generated>",
    "",
    "namespace MBW.Utilities.ManagedSqlite.Sql.Internal.Grammar;",
    "",
    "/// <summary>",
    "/// SQLite's token codes (TK_* in parse.h)",
    "/// </summary>",
    "internal static class TK",
    "{"
};
foreach ((string name, int value) in tokens)
    lines.Add($"    public const int {name} = {value};");
lines.Add("}");
lines.Add("");
lines.Add("/// <summary>");
lines.Add($"/// SQLite {version}'s Lemon parser tables (parse.c) and keywords (mkkeywordhash.c)");
lines.Add("/// </summary>");
lines.Add("internal static class SqliteGrammar");
lines.Add("{");
lines.Add($"    public const string Version = \"{version}\";");
foreach (string c in consts)
    lines.Add($"    public const int {c} = {Define(c)};");
lines.Add("");
lines.Add(CsArray("ushort", "Action", Array("yy_action")));
lines.Add(CsArray("ushort", "Lookahead", Array("yy_lookahead")));
lines.Add(CsArray("ushort", "ShiftOffset", Array("yy_shift_ofst")));
lines.Add(CsArray("short", "ReduceOffset", Array("yy_reduce_ofst")));
lines.Add(CsArray("ushort", "Default", Array("yy_default")));
lines.Add(CsArray("ushort", "Fallback", Array("yyFallback")));
lines.Add(CsArray("ushort", "RuleLhs", Array("yyRuleInfoLhs")));
lines.Add(CsArray("sbyte", "RuleRhsCount", Array("yyRuleInfoNRhs")));
lines.Add(CsStrings("RuleNames", Strings("yyRuleName")));
lines.Add(CsStrings("TokenNames", Strings("yyTokenName")));
lines.Add("    /// <summary>");
lines.Add("    /// The keywords and their token codes, as sqlite3KeywordCode in keywordhash.h finds them");
lines.Add("    /// </summary>");
lines.Add("    public static readonly (string Keyword, int Token)[] Keywords =");
lines.Add("    {");
foreach ((string keyword, string token) in keywords)
    lines.Add($"        (\"{keyword}\", TK.{token}),");
lines.Add("    };");
lines.Add("}");

File.WriteAllText(output, string.Join("\n", lines) + "\n", new UTF8Encoding(false));
return 0;

// The body of a C array in parse.c, without its comments
string Body(string name) =>
    Regex.Replace(Required(Regex.Match(parseC, @"\b" + Regex.Escape(name) + @"\[\] = \{(.*?)\n\};", RegexOptions.Singleline), name + "[] in parse.c"),
        @"/\*.*?\*/", "", RegexOptions.Singleline);

// A missing array or define means the inputs changed shape, which must not quietly give an empty table
string Required(Match match, string what) =>
    match.Success ? match.Groups[1].Value : throw new InvalidOperationException($"{what} was not found");

List<int> Array(string name) => Regex.Matches(Body(name), @"-?\d+").Select(m => int.Parse(m.Value)).ToList();

// The string literals of a C array, as written (escapes kept)
List<string> Strings(string name) => Regex.Matches(Body(name), @"""((?:[^""\\]|\\.)*)""").Select(m => m.Groups[1].Value).ToList();

int Define(string name) => int.Parse(Required(Regex.Match(parseC, "#define " + name + @"\s+\(?(-?\d+)\)?"), "#define " + name + " in parse.c"));

string CsArray(string type, string name, List<int> values)
{
    StringBuilder sb = new($"    public static readonly {type}[] {name} =\n    {{\n");
    for (int i = 0; i < values.Count; i += 20)
    {
        if (i > 0)
            sb.Append('\n');
        sb.Append("        ").Append(string.Join(", ", values.Skip(i).Take(20))).Append(',');
    }

    return sb.Append("\n    };\n").ToString();
}

string CsStrings(string name, List<string> values) =>
    $"    public static readonly string[] {name} =\n    {{\n" + string.Join("\n", values.Select(v => "        \"" + v + "\",")) + "\n    };\n";
